#pragma once

#include <optional>

namespace screen {

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;
};

struct Vec3 {
    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;
};

// 4x4 matrix, row-major storage: m[row][col].
// Convention: column vectors, clip = M * vec4(p, 1).
// If your matrices are column-major (e.g. GLM / OpenGL memory layout),
// pass the transpose or use Matrix4::fromColumnMajor().
struct Matrix4 {
    float m[4][4] = {};

    static Matrix4 fromColumnMajor(const float* data);  // data[16]
    static Matrix4 fromRowMajor(const float* data);     // data[16]
};

struct Viewport {
    float width = 0.0f;
    float height = 0.0f;
};

// Projects a world-space point to screen space (pixels, origin top-left,
// +y down). Returns std::nullopt when the point is on or behind the camera
// plane (clip-space w <= epsilon).
//
// Points in front of the camera but outside the view frustum still return a
// position (possibly off-screen); check bounds yourself if you need to cull.
std::optional<Vec2> worldToScreen(const Matrix4& viewProj,
                                  const Vec3& world,
                                  const Viewport& viewport);

}  // namespace screen

#include "screen.h"

namespace screen {

namespace {
constexpr float kMinW = 1e-6f;
}  // namespace

Matrix4 Matrix4::fromColumnMajor(const float* data) {
    Matrix4 r;
    for (int col = 0; col < 4; ++col)
        for (int row = 0; row < 4; ++row)
            r.m[row][col] = data[col * 4 + row];
    return r;
}

Matrix4 Matrix4::fromRowMajor(const float* data) {
    Matrix4 r;
    for (int row = 0; row < 4; ++row)
        for (int col = 0; col < 4; ++col)
            r.m[row][col] = data[row * 4 + col];
    return r;
}

std::optional<Vec2> worldToScreen(const Matrix4& vp,
                                  const Vec3& p,
                                  const Viewport& viewport) {
    const auto& m = vp.m;

    // clip = M * (p, 1)
    const float cx = m[0][0] * p.x + m[0][1] * p.y + m[0][2] * p.z + m[0][3];
    const float cy = m[1][0] * p.x + m[1][1] * p.y + m[1][2] * p.z + m[1][3];
    const float cw = m[3][0] * p.x + m[3][1] * p.y + m[3][2] * p.z + m[3][3];

    // w is the view-space depth for a standard perspective projection;
    // non-positive means the point is on or behind the camera.
    if (cw <= kMinW)
        return std::nullopt;

    const float invW = 1.0f / cw;
    const float ndcX = cx * invW;  // [-1, 1] inside the frustum
    const float ndcY = cy * invW;  // [-1, 1], +y up

    Vec2 out;
    out.x = (ndcX + 1.0f) * 0.5f * viewport.width;
    out.y = (1.0f - ndcY) * 0.5f * viewport.height;  // flip to +y down
    return out;
}

}  // namespace screen
